INSERT INTO roles(codigo,nombre,alcance) VALUES
('SUPERADMIN','SuperAdmin','GLOBAL'),('ADMINISTRADOR','Administrador','INMUEBLE'),('GERENTE','Gerente','INMUEBLE'),('CONTABILIDAD','Contabilidad','INMUEBLE'),('COMITE','Comité','INMUEBLE'),('PROPIETARIO','Propietario','ESPACIO'),('INQUILINO','Inquilino','ESPACIO'),('OCUPANTE','Ocupante','ESPACIO') ON CONFLICT DO NOTHING;
INSERT INTO permisos(codigo,nombre,modulo,accion) VALUES
('PORTAFOLIO_GLOBAL','Portafolio Global','PORTAFOLIO','READ'),('DASHBOARD_GLOBAL','Dashboard Global','DASHBOARD','READ'),('INMUEBLE_CONSULTAR','Consultar Inmueble','INMUEBLES','READ'),('INMUEBLE_CREAR','Crear Inmueble','INMUEBLES','CREATE'),('INMUEBLE_MODIFICAR','Modificar Inmueble','INMUEBLES','UPDATE'),('INMUEBLE_DESACTIVAR','Desactivar Inmueble','INMUEBLES','UPDATE'),('INMUEBLE_REACTIVAR','Reactivar Inmueble','INMUEBLES','UPDATE'),('INMUEBLE_ELIMINAR','Eliminar Inmueble','INMUEBLES','DELETE'),('INMUEBLE_BRANDING','Gestionar Branding','INMUEBLES','UPDATE'),('ADMINISTRADOR_CREAR','Crear Administrador','USUARIOS','CREATE'),('ADMINISTRADOR_MODIFICAR','Modificar Administrador','USUARIOS','UPDATE'),('ADMINISTRADOR_ASIGNAR','Asignar Administrador','USUARIOS','CREATE'),('ADMINISTRADOR_REVOCAR','Revocar Administrador','USUARIOS','UPDATE'),('SUPERADMIN_CREAR','Crear SuperAdmin','GOBIERNO','CREATE'),('AUDITORIA_GLOBAL','Auditoría Global','AUDITORIA','READ'),('CONFIGURACION_GLOBAL','Configuración Global','CONFIGURACION','UPDATE') ON CONFLICT DO NOTHING;
INSERT INTO rol_permisos SELECT 'ADMINISTRADOR',codigo,TRUE FROM permisos WHERE codigo IN ('INMUEBLE_CONSULTAR','INMUEBLE_MODIFICAR','INMUEBLE_BRANDING') ON CONFLICT DO NOTHING;
INSERT INTO catalogos(codigo,nombre) VALUES('TIPO_INMUEBLE','Tipo De Inmueble'),('TIPO_ESPACIO','Tipo De Espacio'),('ESTADO_ESPACIO','Estado De Espacio') ON CONFLICT DO NOTHING;
INSERT INTO catalogo_valores(catalogo_id,codigo,nombre) SELECT c.id,v.codigo,v.nombre FROM catalogos c JOIN (VALUES('TIPO_INMUEBLE','VERTICAL','Condominio Vertical'),('TIPO_INMUEBLE','HORIZONTAL','Conjunto Horizontal'),('TIPO_INMUEBLE','PLAZA_COMERCIAL','Plaza Comercial'),('TIPO_INMUEBLE','LOCAL_INDIVIDUAL','Establecimiento Individual'),('TIPO_ESPACIO','DEPARTAMENTO','Departamento'),('TIPO_ESPACIO','CASA','Casa'),('TIPO_ESPACIO','LOCAL','Local Comercial'),('TIPO_ESPACIO','OFICINA','Oficina'),('TIPO_ESPACIO','BODEGA','Bodega'),('ESTADO_ESPACIO','OCUPADO','Ocupado'),('ESTADO_ESPACIO','DISPONIBLE','Disponible'))v(cat,codigo,nombre) ON c.codigo=v.cat ON CONFLICT DO NOTHING;
